        """Arm, refresh or stop a dead man's switch for one sub-account: if the countdown reaches zero before you call again, the exchange cancels all of that...

        Never retried; an ambiguous failure raises OrderStateUnknown.
        """
        sub_account_id = self.rt.account(sub_account_id, required=True)
        req = m.ApiCancelOnDisconnectRequest(
            sub_account_id=w.as_str(sub_account_id),
            countdown_time=w.as_str(countdown_time),
        )
        return await self.rt.call(
            specs.ORDER_CANCEL_ON_DISCONNECT,
            req,
            timeout=options.timeout if options is not None else None,
        )

