    async def create_order(
        self,
        *,
        order: m.OrderInput,
        options: CallOptions | None = None,
    ) -> m.ApiCreateOrderResponse:
        """Create an order on the orderbook for this trading account. STABLE_PERP orders require the sub-account to be in multi-asset mode.

        Signed by the client's signer (signature fields left empty are filled in). Never retried; an ambiguous failure raises OrderStateUnknown.
        """
        order = msgspec.structs.replace(order, sub_account_id=self.rt.account(order.sub_account_id))
        order = _with_client_order_id(self.rt, order)
        req = m.ApiCreateOrderRequestInput(order=order)
        return await self.rt.call(
            specs.ORDER_CREATE_ORDER,
            req,
            timeout=options.timeout if options is not None else None,
            sign=signing.sign_order_create_order,
            client_order_id=_client_order_id(order),
        )

