class SyncApi:
    """Blocking versions of the AsyncApi methods, as Grvt methods."""

    _runner: SyncRunner
    _async: AsyncApi

    # account

    def aggregated_account_summary(
        self,
        *,
        options: CallOptions | None = None,
    ) -> m.ApiAggregatedAccountSummaryResponse:
        """Used for requests that do not require any parameters"""
        return self._runner.run(self._async.aggregated_account_summary(options=options))

    def funding_account_summary(self, *, options: CallOptions | None = None) -> m.ApiFundingAccountSummaryResponse:
        """Used for requests that do not require any parameters"""
        return self._runner.run(self._async.funding_account_summary(options=options))

    def get_sub_accounts(self, *, options: CallOptions | None = None) -> m.ApiGetSubAccountsResponse:
        """Used for requests that do not require any parameters"""
        return self._runner.run(self._async.get_sub_accounts(options=options))

    def spot_account_summary(
        self,
        *,
        sub_account_id: int | str | None = None,
        options: CallOptions | None = None,
    ) -> m.ApiSpotSubAccountSummaryResponse:
        """The spot account summary, that reports the total equity and spot balances of a spot sub account"""
        return self._runner.run(self._async.spot_account_summary(sub_account_id=sub_account_id, options=options))

    def sub_account_summary(
        self,
        *,
        sub_account_id: int | str | None = None,
        options: CallOptions | None = None,
    ) -> m.ApiSubAccountSummaryResponse:
        """Query for sub-account details, including base currency balance, all derivative positions, margin levels, and P&L."""
        return self._runner.run(self._async.sub_account_summary(sub_account_id=sub_account_id, options=options))

    # algo_order

    def algo_order_history(
        self,
        *,
        sub_account_id: int | str | None = None,
        type: list[m.e.AlgoOrderType] | None = None,
        start_time: m.Timestamp | None = None,
        end_time: m.Timestamp | None = None,
        limit: int | None = None,
        cursor: str | None = None,
        options: CallOptions | None = None,
    ) -> m.ApiAlgoOrderHistoryResponse:
        """Retrieves the algo order history for the account. Returns one row per terminated or filled parent algo order, not per sub-order."""
        return self._runner.run(
            self._async.algo_order_history(
                sub_account_id=sub_account_id,
                type=type,
                start_time=start_time,
                end_time=end_time,
                limit=limit,
                cursor=cursor,
                options=options,
            )
        )

    def algo_sub_order_history(
        self,
        *,
        algo_order_id: int | str,
        sub_account_id: int | str | None = None,
        options: CallOptions | None = None,
    ) -> m.ApiAlgoSubOrderHistoryResponse:
        """Retrieves the terminal sub-orders of an algo order. A sub-order appears once it reaches a terminal state: partially filled and superseded, fully filled..."""
        return self._runner.run(
            self._async.algo_sub_order_history(
                algo_order_id=algo_order_id,
                sub_account_id=sub_account_id,
                options=options,
            )
        )

    def cancel_algo_order(
        self,
        *,
        sub_account_id: int | str | None = None,
        algo_order_id: int | str | None = None,
        client_order_id: int | str | None = None,
        options: CallOptions | None = None,
    ) -> m.AckResponse:
        """Cancel an algo order for this trading account. This cascades to a full cancel of the sub-order currently resting on the orderbook. Either `algo_order_id` or..."""
        return self._runner.run(
            self._async.cancel_algo_order(
                sub_account_id=sub_account_id,
                algo_order_id=algo_order_id,
                client_order_id=client_order_id,
                options=options,
            )
        )

    def create_algo_order(
        self,
        *,
        order: m.AlgoOrder,
        options: CallOptions | None = None,
    ) -> m.ApiCreateAlgoOrderResponse:
        """Create an algo order for this trading account. Algo trading must be enabled (opted in) for the sub account before creating an algo order. The algo order is..."""
        return self._runner.run(self._async.create_algo_order(order=order, options=options))

    def get_algo_order(
        self,
        *,
        sub_account_id: int | str | None = None,
        algo_order_id: int | str | None = None,
        client_order_id: int | str | None = None,
        options: CallOptions | None = None,
    ) -> m.ApiGetAlgoOrderResponse:
        """Retrieve an algo order for the account. Either `algo_order_id` or `client_order_id` must be provided."""
        return self._runner.run(
            self._async.get_algo_order(
                sub_account_id=sub_account_id,
                algo_order_id=algo_order_id,
                client_order_id=client_order_id,
                options=options,
            )
        )

    def open_algo_orders(
        self,
        *,
        sub_account_id: int | str | None = None,
        kind: list[m.e.Kind] | None = None,
        base: list[str] | None = None,
        quote: list[str] | None = None,
        type: list[m.e.AlgoOrderType] | None = None,
        trigger_filter: m.e.AlgoTriggerFilter | None = None,
        options: CallOptions | None = None,
    ) -> m.ApiOpenAlgoOrdersResponse:
        """Retrieves all open algo orders for the account, including algo orders still pending on their trigger."""
        return self._runner.run(
            self._async.open_algo_orders(
                sub_account_id=sub_account_id,
                kind=kind,
                base=base,
                quote=quote,
                type=type,
                trigger_filter=trigger_filter,
                options=options,
            )
        )

    def algo_order_stream(
        self,
        *,
        sub_account_id: int | str | None = None,
        instrument: str | None = None,
    ) -> SyncSubscription[m.WSAlgoOrderFeedDataV1]:
        """Subscribes to a feed of algo order updates pertaining to algo orders made by your account."""
        return SyncSubscription(
            self._runner,
            self._async.algo_order_stream(sub_account_id=sub_account_id, instrument=instrument),
        )

